import json, glob
rolls=[]
for p in sorted(glob.glob('logs/rollout_timing/rollout_*_dapo.json')):
    rolls.append(json.load(open(p)))
def sig(d):
    out=[]
    for g in d['groups']:
        out.append((tuple(g['task']), tuple(g['rewards']) if g['rewards'] is not None else None, g['reason'], g['disposition']))
    return out
for i in range(6):
    for j in range(i+1,6):
        sa={str(x) for x in sig(rolls[i])}; sb={str(x) for x in sig(rolls[j])}
        print(f'{i}-{j}: signature overlap {len(sa&sb)} / {len(sa)},{len(sb)}')
print()
for i in range(6):
    acc={tuple(g['task']) for g in rolls[i]['groups'] if g['keep']}
    for j in range(i+1,6):
        accj={tuple(g['task']) for g in rolls[j]['groups'] if g['keep']}
        print(f'accepted task overlap {i}-{j}: {len(acc&accj)}')
print()
# which tasks repeat and with what reward sequences
import collections
occ=collections.defaultdict(list)
